"use client";
import {useI18n} from "@/i18n/provider";

import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import * as Dialog from "@radix-ui/react-dialog";
import { ArrowDown, ArrowRight, Bell, BookOpen, CalendarDays, Check, ChevronLeft, ChevronRight, Clock3, Copy, Dumbbell, GraduationCap, LoaderCircle, Pencil, Play, Plus, Search, Settings2, Sparkles, Trash2, Utensils, X } from "lucide-react";
import type { AppData, Category, Exercise, LifeEvent, MealTemplate, Preferences, Task, WorkoutPlan } from "@/lib/types";
import { applyEventOverlay, dateKey, eventsForDate, shiftDate, validatePlan, validateEventTimezone } from "@/lib/schedule";
import { exerciseLogSchema, mealTemplateSchema, planProposalSchema, preferencesSchema, taskSchema, workoutPlanSchema } from "@/lib/validation";
import "./modules.css";

export interface ModuleProps {
  data: AppData;
  setData: (updater: (current: AppData) => AppData) => void;
  selectedDate: string;
  onDateChange: (date: string) => void;
  onEditEvent: (event?: LifeEvent, defaults?: Partial<LifeEvent>) => void;
  onToast: (message: string) => void;
}

const categories: Category[] = ["study", "work", "nutrition", "workout", "personal", "rest"];
const uid = () => crypto.randomUUID();
const mondayOf = (day: string) => shiftDate(day, -((new Date(`${day}T12:00:00`).getDay() + 6) % 7));
const numeric = (form: FormData, key: string, fallback = 0) => Number(form.get(key) ?? fallback);
const optionalNumber = (form: FormData, key: string) => String(form.get(key) ?? "").trim() ? Number(form.get(key)) : undefined;
const str = (form: FormData, key: string) => String(form.get(key) ?? "").trim();

function Modal({ open, onOpenChange, title, description, children }: { open: boolean; onOpenChange: (open: boolean) => void; title: string; description?: string; children: ReactNode }) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  return <Dialog.Root open={open} onOpenChange={onOpenChange}><Dialog.Portal><Dialog.Overlay className="module-overlay" /><Dialog.Content className="module-modal"><div className="module-modal-heading"><div><Dialog.Title>{title}</Dialog.Title><Dialog.Description className="muted">{description ?? tr("Make a little room for what matters.")}</Dialog.Description></div><Dialog.Close asChild><button className="icon-btn" aria-label={tr("Close dialog")}><X size={20} /></button></Dialog.Close></div>{children}</Dialog.Content></Dialog.Portal></Dialog.Root>;
}

function SectionHeading({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text: string; action?: ReactNode }) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  return <div className="module-page-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p className="muted">{text}</p></div>{action}</div>;
}

function Empty({ icon, title, text, action }: { icon: ReactNode; title: string; text: string; action?: ReactNode }) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  return <div className="module-empty"><div className="module-empty-icon">{icon}</div><h3>{title}</h3><p className="muted">{text}</p>{action}</div>;
}

function EventMini({ event, onClick, timeFormat = "24" }: { event: LifeEvent; onClick: () => void; timeFormat?: "12" | "24" }) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  return <button onClick={onClick} className={`module-event category-${event.category} ${event.status === "completed" ? "is-done" : ""}`}><span className="module-event-time">{event.startTime} — {event.endTime}</span><strong>{event.title}</strong>{event.location && <span className="muted">{event.location}</span>}{event.fixed && <span className="module-fixed">{tr("Fixed")}</span>}</button>;
}

export function CalendarView(props: ModuleProps) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const { data, selectedDate, onDateChange, onEditEvent } = props;
  const [view, setView] = useState<"day" | "week" | "month">("week");
  const [category, setCategory] = useState("all");
  const [classesOnly, setClassesOnly] = useState(false);
  const base = view === "month" ? `${selectedDate.slice(0, 7)}-01` : mondayOf(selectedDate);
  const monthStart = mondayOf(base);
  const days = Array.from({ length: view === "month" ? 42 : view === "week" ? 7 : 1 }, (_, i) => shiftDate(view === "month" ? monthStart : view === "week" ? base : selectedDate, i));
  const getEvents = (day: string) => eventsForDate(data.events, day, data.preferences.timezone).filter(e => (category === "all" || e.category === category) && (!classesOnly || e.category === "study" && (!!e.recurrence || !!e.parentId && data.events.some(master=>master.id===e.parentId && master.category==='study'))));
  const move = (amount: number) => {
    if (view === "month") { const d = new Date(`${selectedDate.slice(0, 7)}-01T12:00:00`); d.setMonth(d.getMonth() + amount); onDateChange(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-01`); }
    else onDateChange(shiftDate(selectedDate, amount * (view === "week" ? 7 : 1)));
  };
  return <div className="module-page"><SectionHeading eyebrow={tr("THE BIGGER PICTURE")} title={tr("A little perspective.")} text={tr("Your week, with room for life in between.")} action={<button className="btn btn-primary" onClick={() => onEditEvent(undefined, { date: selectedDate })}><Plus size={17} /> {tr("Add activity")}</button>} />
    <div className="module-toolbar"><div className="module-date-nav"><button className="icon-btn" aria-label={tr("Previous period")} onClick={() => move(-1)}><ChevronLeft size={19} /></button><h2>{dayLabel(selectedDate, { month: "long", year: "numeric" })}</h2><button className="icon-btn" aria-label={tr("Next period")} onClick={() => move(1)}><ChevronRight size={19} /></button></div><div className="module-segment">{(["day", "week", "month"] as const).map(v => <button key={v} className={view === v ? "selected" : ""} onClick={() => setView(v)}>{humanCategory(v)}</button>)}</div></div>
    <div className="module-filter-row"><select className="field" aria-label={tr("Filter calendar category")} value={category} onChange={e => setCategory(e.target.value)}><option value="all">{tr("All activities")}</option>{categories.map(c => <option key={c} value={c}>{humanCategory(c)}</option>)}</select><button className={`btn ${classesOnly ? "module-filter-active" : "btn-ghost"}`} onClick={() => setClassesOnly(!classesOnly)}><GraduationCap size={16} /> {tr("University timetable")}</button><span className="muted module-filter-help">{tr("Recurring classes appear automatically.")}</span></div>
    {view === "month" ? <div className="module-month panel"><div className="module-month-weekdays">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map(d => <span key={d}>{tr(d)}</span>)}</div><div className="module-month-grid">{days.map(day => { const list = getEvents(day); return <div className={`module-month-day ${day.slice(0, 7) !== selectedDate.slice(0, 7) ? "outside" : ""} ${day === selectedDate ? "selected" : ""}`} key={day}><button className="module-day-number" aria-label={tr("Open {p0}", {p0: dayLabel(day)})} onClick={() => { onDateChange(day); setView("day"); }}>{Number(day.slice(-2))}</button><div className="module-month-events">{list.slice(0, 3).map(e => <button className={`module-month-event category-${e.category}`} key={e.id} onClick={() => onEditEvent(e)}><span>{formatTime(e.startTime, data.preferences.timeFormat)}</span> {e.title}</button>)}{list.length > 3 && <button className="module-more" onClick={() => { onDateChange(day); setView("day"); }}>+{list.length - 3} {tr("more")}</button>}</div>{list.length > 0 && <div className="module-mobile-dots">{list.slice(0, 4).map(e => <span key={e.id} className={`category-${e.category}`} />)}</div>}</div>; })}</div></div>
      : <div className={`module-calendar-${view}`}>{days.map(day => { const list = getEvents(day); return <section className={`module-calendar-column ${day === selectedDate ? "selected" : ""}`} key={day}><button className="module-calendar-date" onClick={() => onDateChange(day)}><span>{dayLabel(day, { weekday: "short" })}</span><strong>{day.slice(-2)}</strong></button><div className="module-calendar-events">{list.map(e => <EventMini key={e.id} event={e} timeFormat={data.preferences.timeFormat} onClick={() => onEditEvent(e)} />)}{!list.length && <p className="module-calendar-free">{tr("A little breathing room")}</p>}<button className="module-calendar-add" onClick={() => onEditEvent(undefined, { date: day, category: classesOnly ? "study" : undefined })}><Plus size={15} /><span>{tr("Add activity")}</span></button></div></section>; })}</div>}
    {classesOnly && <div className="module-info"><BookOpen size={18} /><p>{tr("Add an activity in Study, then turn on weekly recurrence. Open an occurrence to change just that class, cancel a session, or edit the series.")}</p></div>}
  </div>;
}

export function TasksView({ data, setData, selectedDate, onEditEvent, onToast }: ModuleProps) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const [filter, setFilter] = useState<"open" | "completed" | "all">("open");
  const [search, setSearch] = useState("");
  const [draft, setDraft] = useState<Task | "new" | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  useEffect(() => { setConfirmDelete(false); }, [draft]);
  const tasks = data.tasks.filter(t => (filter === "all" || t.completed === (filter === "completed")) && `${t.title} ${t.description}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => (a.completed === b.completed ? 0 : a.completed ? 1 : -1) || (a.deadline || "9999").localeCompare(b.deadline || "9999") || ({ high: 0, medium: 1, low: 2 }[a.priority] - { high: 0, medium: 1, low: 2 }[b.priority]));
  const editTask = draft && draft !== "new" ? draft : null;
  function save(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const task: Task = { id: editTask?.id ?? uid(), title: str(f, "title"), description: str(f, "description"), priority: str(f, "priority") as Task["priority"], deadline: str(f, "deadline"), estimatedMinutes: numeric(f, "estimatedMinutes", 60), category: str(f, "category") as Category, completed: editTask?.completed ?? false }; const parsed = taskSchema.safeParse(task); if (!parsed.success) { onToast(issue(parsed.error.issues[0]??{})); return; } setData(s => ({ ...s, tasks: editTask ? s.tasks.map(t => t.id === task.id ? task : t) : [...s.tasks, task] })); setDraft(null); onToast(editTask ? tr("Task updated") : tr("Task added. You can schedule it when you’re ready.")); }
  return <div className="module-page"><SectionHeading eyebrow={tr("ONE THING AT A TIME")} title={tr("Make space for progress.")} text={tr("{p0} open tasks. Your deadlines and your schedule, thoughtfully separate.", {p0: data.tasks.filter(t => !t.completed).length})} action={<button className="btn btn-primary" onClick={() => setDraft("new")}><Plus size={17} /> {tr("New task")}</button>} />
    <div className="module-toolbar"><div className="module-segment">{(["open", "completed", "all"] as const).map(f => <button className={filter === f ? "selected" : ""} key={f} onClick={() => setFilter(f)}>{humanCategory(f)}</button>)}</div><label className="module-search"><Search size={16} /><input aria-label={tr("Search tasks")} placeholder={tr("Find a task…")} value={search} onChange={e => setSearch(e.target.value)} /></label></div>
    <div className="module-task-list">{tasks.map(t => { const overdue = !t.completed && !!t.deadline && t.deadline < dateKey(new Date(), data.preferences.timezone); const scheduled = data.events.filter(e => e.details?.taskId === t.id); return <article className={`panel module-task ${t.completed ? "is-done" : ""}`} key={t.id}><button className={`module-task-check ${t.completed ? "checked" : ""}`} aria-label={`${t.completed ? tr("Reopen") : tr("Complete")} ${t.title}`} onClick={() => setData(s => ({ ...s, tasks: s.tasks.map(task => task.id === t.id ? { ...task, completed: !task.completed } : task) }))}>{t.completed && <Check size={17} />}</button><div className="module-task-body"><div className="module-task-title"><h3>{t.title}</h3><span className={`module-priority priority-${humanCategory(t.priority)}`}>{humanCategory(t.priority)}</span></div>{t.description && <p className="muted">{t.description}</p>}<div className="module-task-meta"><span className={`module-category-dot category-${t.category}`} />{humanCategory(t.category)}<span>·</span><Clock3 size={13} />{formatDuration(t.estimatedMinutes)}{t.deadline && <><span>·</span><span className={overdue ? "module-danger-text" : ""}>{overdue ? "Overdue · " : "Due "}{dayLabel(t.deadline.slice(0, 10))}</span></>}{scheduled.length > 0 && <span className="module-scheduled">{tr("tasks.sessions",{count:scheduled.length})}</span>}</div></div><div className="module-task-actions">{!t.completed && <button className="btn btn-ghost" onClick={() => onEditEvent(undefined, { title: t.title, description: t.description, category: t.category, date: selectedDate, details: { taskId: t.id, estimatedMinutes: t.estimatedMinutes } })}><CalendarDays size={16} /><span>{tr("Schedule")}</span></button>}<button className="icon-btn" aria-label={tr("Edit {p0}", {p0: t.title})} onClick={() => setDraft(t)}><Pencil size={16} /></button></div></article>; })}</div>
    {!tasks.length && <Empty icon={<Check size={26} />} title={search ? tr("No matching tasks") : filter === "completed" ? tr("Progress will live here") : tr("A clear mind starts here")} text={search ? tr("Try another word or switch your filter.") : tr("Capture what’s on your mind. Give it a time when you’re ready.")} action={<button className="btn btn-primary" onClick={() => setDraft("new")}><Plus size={16} /> {tr("Add a task")}</button>} />}
    <Modal open={!!draft} onOpenChange={open => !open && setDraft(null)} title={editTask ? tr("Edit task") : tr("Something to work toward")} description={tr("A deadline is when it’s due. You can schedule working time separately.")}><form onSubmit={save} className="module-form" key={editTask?.id ?? "new"}><label className="label">{tr("Task name")}<input className="field" name="title" required maxLength={200} defaultValue={editTask?.title} placeholder={tr("Finish the Java assignment")} autoFocus /></label><label className="label">{tr("Description")}<textarea className="field" name="description" defaultValue={editTask?.description} rows={3} maxLength={4000} /></label><div className="form-grid"><label className="label">{tr("Category")}<select className="field" name="category" defaultValue={editTask?.category ?? "work"}>{categories.map(c => <option key={c} value={c}>{humanCategory(c)}</option>)}</select></label><label className="label">{tr("Priority")}<select className="field" name="priority" defaultValue={editTask?.priority ?? "medium"}><option value="low">{tr("Low")}</option><option value="medium">{tr("Medium")}</option><option value="high">{tr("High")}</option></select></label><label className="label">{tr("Deadline · optional")}<input className="field" type="date" name="deadline" defaultValue={editTask?.deadline?.slice(0, 10)} /></label><label className="label">{tr("Estimated minutes")}<input className="field" name="estimatedMinutes" type="number" min={5} max={10080} step={5} required defaultValue={editTask?.estimatedMinutes ?? 60} /></label></div><div className="module-form-actions">{editTask && <button type="button" className="btn module-danger-text" onClick={() => { if (!confirmDelete) { setConfirmDelete(true); return; } setData(s => ({ ...s, tasks: s.tasks.filter(t => t.id !== editTask.id), events: s.events.map(e => { if (e.details?.taskId !== editTask.id) return e; const details = { ...e.details }; delete details.taskId; return { ...e, details }; }) })); setDraft(null); onToast(tr("Task deleted. Scheduled sessions were kept.")); }}><Trash2 size={16} />{confirmDelete ? tr("Confirm delete") : tr("Delete")}</button>}<button type="button" className="btn btn-ghost" onClick={() => setDraft(null)}>{tr("Cancel")}</button><button className="btn btn-primary" type="submit">{tr("Save task")}</button></div></form></Modal>
  </div>;
}

export function NutritionView(props: ModuleProps) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const { data, setData, selectedDate, onDateChange, onEditEvent, onToast } = props;
  const [tab, setTab] = useState<"day" | "week" | "templates" | "history">("day");
  const [draft, setDraft] = useState<MealTemplate | "new" | null>(null);
  const [confirmRemove, setConfirmRemove] = useState(false);
  useEffect(() => { setConfirmRemove(false); }, [draft]);
  const edited = draft && draft !== "new" ? draft : null;
  const days = tab === "week" ? Array.from({ length: 7 }, (_, i) => shiftDate(mondayOf(selectedDate), i)) : [selectedDate];
  const meals = eventsForDate(data.events, selectedDate, data.preferences.timezone).filter(e => e.category === "nutrition");
  const calories = meals.reduce((n, e) => n + (typeof e.details?.calories === "number" ? e.details.calories : 0), 0);
  const hasCalories = meals.some(e => typeof e.details?.calories === "number");
  function save(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const meal: MealTemplate = { id: edited?.id ?? uid(), name: str(f, "name"), description: str(f, "description"), calories: optionalNumber(f, "calories"), protein: optionalNumber(f, "protein"), carbs: optionalNumber(f, "carbs"), fat: optionalNumber(f, "fat") }; const parsed = mealTemplateSchema.safeParse(meal); if (!parsed.success) { onToast(issue(parsed.error.issues[0]??{})); return; } setData(s => ({ ...s, mealTemplates: edited ? s.mealTemplates.map(m => m.id === edited.id ? meal : m) : [...s.mealTemplates, meal] })); setDraft(null); onToast(tr("Meal template saved")); }
  return <div className="module-page"><SectionHeading eyebrow={tr("NOURISH YOUR DAY")} title={tr("A little care, every meal.")} text={tr("Simple plans, familiar favorites, and time to enjoy them.")} action={<button className="btn btn-primary" onClick={() => onEditEvent(undefined, { category: "nutrition", date: selectedDate, startTime: "12:00", endTime: "12:30" })}><Plus size={17} /> {tr("Plan a meal")}</button>} />
    <div className="module-toolbar"><div className="module-segment">{(["day", "week", "templates", "history"] as const).map(t => <button key={t} className={tab === t ? "selected" : ""} onClick={() => setTab(t)}>{({ day: tr("Today"), week: tr("Week"), templates: tr("Favorites"), history: tr("History") })[t]}</button>)}</div>{tab !== "templates" && <input className="field module-date-input" type="date" aria-label={tr("Meal planner date")} value={selectedDate} onChange={e => e.target.value && onDateChange(e.target.value)} />}</div>
    {tab === "templates" ? <><div className="module-section-heading"><h2>{tr("Your familiar favorites")}</h2><button className="btn btn-ghost" onClick={() => setDraft("new")}><Plus size={16} />{tr("New template")}</button></div><div className="module-card-grid">{data.mealTemplates.map(m => <article className="panel module-template-card" key={m.id}><div className="module-template-icon nutrition"><Utensils size={21} /></div><h3>{m.name}</h3><p className="muted">{m.description || tr("A favorite worth making time for.")}</p>{m.calories !== undefined && <div className="module-macros"><span>~{m.calories} kcal</span>{m.protein !== undefined && <span>{m.protein}{tr("g protein")}</span>}<small>{tr("Estimates")}</small></div>}<div className="module-card-actions"><button className="btn btn-ghost" onClick={() => onEditEvent(undefined, { title: m.name, description: m.description, category: "nutrition", date: selectedDate, startTime: "12:00", endTime: "12:30", details: { templateId: m.id, calories: m.calories, protein: m.protein, carbs: m.carbs, fat: m.fat } })}><Plus size={16} />{tr("Schedule")}</button><button className="icon-btn" aria-label={tr("Edit {p0}", {p0: m.name})} onClick={() => setDraft(m)}><Pencil size={15} /></button></div></article>)}</div>{!data.mealTemplates.length && <Empty icon={<Utensils size={27} />} title={tr("Your favorites, one tap away")} text={tr("Save a familiar meal, then add it to any day.")} action={<button className="btn btn-primary" onClick={() => setDraft("new")}><Plus size={16} />{tr("Save a meal")}</button>} />}</>
      : tab === "history" ? <div className="module-history-list">{data.events.filter(e => e.category === "nutrition" && e.status === "completed").sort((a, b) => b.date.localeCompare(a.date)).map(e => <article className="panel module-history-item" key={e.id}><span className="module-template-icon nutrition"><Utensils size={19} /></span><div><h3>{e.title}</h3><p className="muted">{dayLabel(e.date)} · {e.startTime}</p></div><span className="module-history-done"><Check size={15} />{tr("Enjoyed")}</span><button className="icon-btn" aria-label={tr("View {p0}", {p0: e.title})} onClick={() => onEditEvent(e)}><ArrowRight size={17} /></button></article>)}{!data.events.some(e => e.category === "nutrition" && e.status === "completed") && <Empty icon={<Utensils size={25} />} title={tr("A record of little rituals")} text={tr("Complete a meal on your timeline and it will appear here.")} />}</div>
      : <><div className="module-nutrition-note"><Utensils size={22} /><div><strong>{tab === "day" ? tr("meals.planned",{count:meals.length}) : tr("A well-fed week")}</strong><p className="muted">{hasCalories && tab === "day" ? tr("~{p0} kcal from meals with data · estimates, not a daily target", {p0: calories.toLocaleString(language==='vi'?'vi-VN':'en-US')}) : tr("No numbers needed. A meal and a time are enough.")}</p></div></div><div className={tab === "week" ? "module-meal-week" : "module-meal-day"}>{days.map(day => { const list = eventsForDate(data.events, day, data.preferences.timezone).filter(e => e.category === "nutrition"); return <section className="panel module-meal-day-panel" key={day}><div className="module-section-heading"><h2>{dayLabel(day)}</h2><button className="icon-btn" aria-label={tr("Plan a meal for {p0}", {p0: dayLabel(day)})} onClick={() => onEditEvent(undefined, { date: day, category: "nutrition", startTime: "12:00", endTime: "12:30" })}><Plus size={17} /></button></div>{list.map(e => <EventMini key={e.id} event={e} timeFormat={data.preferences.timeFormat} onClick={() => onEditEvent(e)} />)}{!list.length && <p className="module-calendar-free">{tr("No meals planned yet.")}</p>}</section>; })}</div><div className="module-info"><Utensils size={18} /><p>{tr("Nutrition values are optional and shown as estimates. Add meal notes, portions, or macros in an activity’s details.")}</p></div></>}
    <Modal open={!!draft} onOpenChange={o => !o && setDraft(null)} title={edited ? tr("Edit a favorite") : tr("Save a familiar favorite")} description={tr("Keep it simple. Nutrition values are completely optional.")}><form className="module-form" onSubmit={save} key={edited?.id ?? "new"}><label className="label">{tr("Meal name")}<input className="field" name="name" required maxLength={200} defaultValue={edited?.name} placeholder={tr("Cơm gà & vegetables")} autoFocus /></label><label className="label">{tr("Food, portions, or notes")}<textarea className="field" name="description" maxLength={4000} rows={3} defaultValue={edited?.description} /></label><div className="form-grid">{(["calories", "protein", "carbs", "fat"] as const).map(k => <label className="label" key={k}>{humanCategory(k)} {k !== "calories" ? "(g)" : "(kcal)"} {tr("· estimated")}<input className="field" type="number" min={0} max={100000} step="any" name={k} defaultValue={edited?.[k]} /></label>)}</div>{confirmRemove && <p className="module-remove-notice" role="alert">{tr("Remove this template? Your planned meals and history will be kept. Click Confirm remove to continue.")}</p>}<div className="module-form-actions">{edited && <button type="button" className="btn module-danger-text" onClick={() => { if (!confirmRemove) { setConfirmRemove(true); return; } setData(s => ({ ...s, mealTemplates: s.mealTemplates.filter(m => m.id !== edited.id) })); setDraft(null); onToast(tr("Template removed. Planned meals were kept.")); }}><Trash2 size={16} />{confirmRemove ? tr("Confirm remove") : tr("Remove")}</button>}<button type="button" className="btn btn-ghost" onClick={() => setDraft(null)}>{tr("Cancel")}</button><button className="btn btn-primary">{tr("Save favorite")}</button></div></form></Modal>
  </div>;
}

export function WorkoutView({ data, setData, selectedDate, onDateChange, onEditEvent, onToast }: ModuleProps) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const [tab, setTab] = useState<"plans" | "sessions" | "history">("plans");
  const [draft, setDraft] = useState<WorkoutPlan | "new" | null>(null);
  const [confirmRemove, setConfirmRemove] = useState(false);
  useEffect(() => { setConfirmRemove(false); }, [draft]);
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [logging, setLogging] = useState<LifeEvent | null>(null);
  const edited = draft && draft !== "new" ? draft : null;
  const recurringSessions = Array.from({ length: 7 }, (_, i) => shiftDate(mondayOf(selectedDate), i)).flatMap(day => eventsForDate(data.events, day, data.preferences.timezone)).filter(e => e.category === "workout" && e.parentId && e.status !== "completed");
  const sessions = [...new Map((tab === "history" ? data.events.filter(e => e.category === "workout" && e.status === "completed") : [...data.events.filter(e => e.category === "workout" && !e.recurrence && e.status !== "completed"), ...recurringSessions]).map(e => [e.id, e])).values()].sort((a, b) => tab === "history" ? b.date.localeCompare(a.date) : a.date.localeCompare(b.date) || a.startTime.localeCompare(b.startTime));
  const logPlan = data.workoutPlans.find(p => p.id === logging?.details?.planId);
  function edit(plan?: WorkoutPlan) { setDraft(plan ?? "new"); setExercises(plan?.exercises.map(e => ({ ...e })) ?? []); }
  function save(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const f = new FormData(e.currentTarget); const plan: WorkoutPlan = { id: edited?.id ?? uid(), name: str(f, "name"), type: str(f, "type"), description: str(f, "description"), exercises: exercises.map(x => ({ ...x, name: x.name.trim() })).filter(x => x.name) }; const parsed = workoutPlanSchema.safeParse(plan); if (!parsed.success) { onToast(issue(parsed.error.issues[0]??{})); return; } setData(s => ({ ...s, workoutPlans: edited ? s.workoutPlans.map(p => p.id === edited.id ? plan : p) : [...s.workoutPlans, plan] })); setDraft(null); onToast(tr("Workout plan saved")); }
  function updateExercise(id: string, key: keyof Exercise, value: string) { setExercises(xs => xs.map(x => x.id === id ? { ...x, [key]: key === "name" ? value : Math.max(0, Number(value)) } : x)); }
  function complete(e: FormEvent<HTMLFormElement>) { e.preventDefault(); if (!logging) return; const target = data.events.find(event => event.id === logging.id || (logging.details?.sessionKey && event.details?.sessionKey === logging.details.sessionKey)) ?? logging; const f = new FormData(e.currentTarget); const entries = (logPlan?.exercises ?? []).map(x => ({ id: uid(), eventId: target.id, exerciseId: x.id, date: logging.date, sets: numeric(f, `${x.id}-sets`, x.sets), reps: numeric(f, `${x.id}-reps`, x.reps), weight: numeric(f, `${x.id}-weight`, x.weight), notes: str(f, "notes") })); const checked = entries.map(entry => exerciseLogSchema.safeParse(entry)); const invalid = checked.find(result => !result.success); if (invalid && !invalid.success) { onToast(issue(invalid.error.issues[0]??{})); return; } setData(s => ({ ...s, events: s.events.map(event => event.id === target.id ? { ...event, status: "completed", details: { ...event.details, completedAt: new Date().toISOString(), workoutNotes: str(f, "notes"), exerciseNames: Object.fromEntries((logPlan?.exercises ?? []).map(x => [x.id, x.name])) } } : event), exerciseLogs: [...s.exerciseLogs, ...entries] })); setLogging(null); onToast(tr("Session complete. A little stronger, one day at a time.")); }
  return <div className="module-page"><SectionHeading eyebrow={tr("SHOW UP FOR YOURSELF")} title={tr("Progress at your pace.")} text={tr("Plan your movement. Keep a record of how far you’ve come.")} action={<button className="btn btn-primary" onClick={() => edit()}><Plus size={17} /> {tr("Create a plan")}</button>} /><div className="module-toolbar"><div className="module-segment">{(["plans", "sessions", "history"] as const).map(t => <button className={tab === t ? "selected" : ""} key={t} onClick={() => setTab(t)}>{humanCategory(t)}</button>)}</div><button className="btn btn-ghost" onClick={() => onEditEvent(undefined, { category: "workout", date: selectedDate })}><CalendarDays size={16} />{tr("Schedule a session")}</button></div>
    {tab === "plans" ? <div className="module-card-grid">{data.workoutPlans.map(p => <article className="panel module-workout-card" key={p.id}><div className="module-workout-card-top"><span className="module-template-icon workout"><Dumbbell size={23} /></span><span className="badge">{humanCategory(p.type)}</span></div><h2>{p.name}</h2><p className="muted">{p.description || tr("Your next chance to feel good.")}</p><div className="module-exercise-preview">{p.exercises.slice(0, 4).map(x => <div key={x.id}><span>{x.name}</span><strong>{x.sets} × {x.reps}</strong></div>)}{p.exercises.length > 4 && <p className="muted">+{p.exercises.length - 4} {tr("more exercises")}</p>}{!p.exercises.length && <p className="muted">{tr("Add exercises whenever you’re ready.")}</p>}</div><div className="module-card-actions"><button className="btn btn-primary" onClick={() => onEditEvent(undefined, { title: p.name, description: p.description, category: "workout", date: selectedDate, details: { planId: p.id, workoutType: p.type } })}><CalendarDays size={16} />{tr("Schedule")}</button><button className="icon-btn" aria-label={tr("Copy {p0}", {p0: p.name})} onClick={() => { setData(s => ({ ...s, workoutPlans: [...s.workoutPlans, { ...p, id: uid(), name: `${p.name} (${tr('copy.suffix')})`, exercises: p.exercises.map(x => ({ ...x, id: uid() })) }] })); onToast(tr("Plan copied")); }}><Copy size={16} /></button><button className="icon-btn" aria-label={tr("Edit {p0}", {p0: p.name})} onClick={() => edit(p)}><Pencil size={16} /></button></div></article>)}{!data.workoutPlans.length && <Empty icon={<Dumbbell size={29} />} title={tr("Make movement a ritual")} text={tr("A gym session, a walk, badminton with friends. Start with a plan that feels like you.")} action={<button className="btn btn-primary" onClick={() => edit()}><Plus size={16} />{tr("Create your first plan")}</button>} />}</div>
      : <div className="module-history-list">{sessions.map(e => { const logs = data.exerciseLogs.filter(l => l.eventId === e.id); return <article className="panel module-workout-session" key={e.id}><div className="module-session-info"><span className="module-template-icon workout"><Dumbbell size={22} /></span><div><h3>{e.title}</h3><p className="muted">{dayLabel(e.date)} · {e.startTime} — {e.endTime}</p>{tab === "history" && <p className="module-session-result">{logs.length ? tr("{p0} exercises logged · {p1} sets", {p0: logs.length, p1: logs.reduce((n, l) => n + l.sets, 0)}) : tr("Session completed")}</p>}</div></div><div className="module-session-actions">{tab !== "history" && <button className="btn btn-primary" onClick={() => { const started = { ...e, details: { ...e.details, startedAt: e.details?.startedAt ?? new Date().toISOString(), sessionKey: e.details?.sessionKey ?? uid() } }; setData(s => ({ ...s, events: applyEventOverlay(s.events, [started], { materializeOccurrences: true }) })); setLogging(started); }}><Play size={15} />{e.details?.startedAt ? tr("Continue & log") : tr("Start session")}</button>}<button className="btn btn-ghost" onClick={() => onEditEvent(e)}>{tr("Details")}<ArrowRight size={15} /></button></div>{tab === "history" && !!logs.length && <div className="module-log-summary">{logs.map(l => <span key={l.id}>{data.workoutPlans.flatMap(p => p.exercises).find(x => x.id === l.exerciseId)?.name ?? (e.details?.exerciseNames as Record<string, string> | undefined)?.[l.exerciseId] ?? tr("Exercise")}: {l.sets} × {l.reps}{l.weight > 0 ? ` · ${l.weight} kg` : ""}</span>)}</div>}</article>; })}{!sessions.length && <Empty icon={<Dumbbell size={26} />} title={tab === "history" ? tr("Every session counts") : tr("Your next good habit")} text={tab === "history" ? tr("Completed workouts and exercise logs will appear here.") : tr("Schedule a workout from one of your plans, or add a session to your timeline.")} />}</div>}
    <Modal open={!!draft} onOpenChange={o => !o && setDraft(null)} title={edited ? tr("Edit workout plan") : tr("Build your next good habit")} description={tr("A reusable plan. Your scheduled sessions live on the timeline.")}><form className="module-form" onSubmit={save} key={edited?.id ?? "new"}><div className="form-grid"><label className="label">{tr("Plan name")}<input className="field" name="name" required maxLength={200} defaultValue={edited?.name} placeholder={tr("Push day")} autoFocus /></label><label className="label">{tr("Session type")}<select className="field" name="type" defaultValue={edited?.type ?? "Push"}>{["Push", "Pull", "Legs", "Upper", "Lower", "Full Body", "Cardio", "Badminton", "Rest Day", "Custom Workout"].map(t => <option key={t} value={t}>{humanCategory(t)}</option>)}</select></label></div><label className="label">{tr("Description")}<textarea className="field" name="description" maxLength={4000} defaultValue={edited?.description} rows={2} /></label><div className="module-section-heading"><h3>{tr("Exercises")}</h3><button type="button" className="btn btn-ghost" onClick={() => setExercises(xs => [...xs, { id: uid(), name: "", sets: 3, reps: 10, weight: 0, restSeconds: 60 }])}><Plus size={15} />{tr("Add exercise")}</button></div><div className="module-exercise-editor">{exercises.map((x, i) => <div className="module-exercise-edit-row" key={x.id}><label className="label module-exercise-name">{tr("workout.exercise",{count:i+1})}<input className="field" required maxLength={200} value={x.name} onChange={e => updateExercise(x.id, "name", e.target.value)} placeholder={tr("Bench press")} /></label>{(["sets", "reps", "weight", "restSeconds"] as const).map(k => <label className="label" key={k}>{{ sets: tr("Sets"), reps: tr("Reps"), weight: "kg", restSeconds: tr("Rest (s)") }[k]}<input className="field" type="number" min={k === "sets" || k === "reps" ? 1 : 0} max={k === "restSeconds" ? 3600 : 1000} step={k === "weight" ? 0.5 : 1} required value={x[k]} onChange={e => updateExercise(x.id, k, e.target.value)} /></label>)}<button type="button" className="icon-btn module-exercise-remove" aria-label={tr("Remove exercise {p0}", {p0: i + 1})} onClick={() => setExercises(xs => xs.filter(item => item.id !== x.id))}><X size={16} /></button></div>)}</div><div className="module-form-actions">{edited && <button type="button" className="btn module-danger-text" onClick={() => { if (!confirmRemove) { setConfirmRemove(true); return; } setData(s => ({ ...s, workoutPlans: s.workoutPlans.filter(p => p.id !== edited.id) })); setDraft(null); onToast(tr("Plan removed. Your session history was kept.")); }}><Trash2 size={16} />{confirmRemove ? tr("Confirm remove") : tr("Remove plan")}</button>}<button type="button" className="btn btn-ghost" onClick={() => setDraft(null)}>{tr("Cancel")}</button><button className="btn btn-primary">{tr("Save plan")}</button></div></form></Modal>
    <Modal open={!!logging} onOpenChange={o => !o && setLogging(null)} title={logging?.title ?? tr("Workout session")} description={tr("Adjust these numbers to what you actually did. Your progress is personal.")}><form className="module-form" onSubmit={complete} key={logging?.id}>{(logPlan?.exercises ?? []).map(x => <div className="module-session-log" key={x.id}><h3>{x.name}</h3><div className="form-grid three">{(["sets", "reps", "weight"] as const).map(k => <label className="label" key={k}>{k === "weight" ? tr("Weight (kg)") : humanCategory(k)}<input className="field" name={`${x.id}-${k}`} type="number" min={k === "weight" ? 0 : 1} max={1000} step={k === "weight" ? 0.5 : 1} defaultValue={x[k]} required /></label>)}</div><p className="muted">{tr("workout.rest",{seconds:x.restSeconds})}</p></div>)}{!logPlan?.exercises.length && <p className="muted">{tr("Enjoy your session. Add how it went in your notes below.")}</p>}<label className="label">{tr("How did it feel?")}<textarea className="field" name="notes" maxLength={4000} rows={3} placeholder={tr("Energy, form, or a little win…")} /></label><div className="module-form-actions"><button className="btn btn-ghost" type="button" onClick={() => setLogging(null)}>{tr("Keep session open")}</button><button className="btn btn-primary"><Check size={17} />{tr("Complete & save logs")}</button></div></form></Modal>
  </div>;
}

export function SettingsView({ data, setData, onToast }: ModuleProps) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const [draft, setDraft] = useState<Preferences>(data.preferences);
  const [notification, setNotification] = useState<NotificationPermission | "unsupported">("default");
  useEffect(() => { setDraft(data.preferences); }, [data.preferences]);
  useEffect(() => { setNotification("Notification" in window ? Notification.permission : "unsupported"); }, []);
  function update<K extends keyof Preferences>(key: K, value: Preferences[K]) { setDraft(s => ({ ...s, [key]: value })); }
  function input(key: keyof Preferences, label: string, type = "text") { return <label className="label" key={key}>{label}<input className="field" type={type} value={String(draft[key] ?? "")} maxLength={2000} required={key === "displayName" || key === "timezone"} onChange={e => update(key, (type === "number" ? Number(e.target.value) : e.target.value) as never)} {...(type === "number" ? { min: 0, max: 1440 } : {})} /></label>; }
  function save(e: FormEvent) { e.preventDefault(); try { new Intl.DateTimeFormat("en", { timeZone: draft.timezone }); } catch { onToast(tr("Please enter a valid timezone, such as Asia/Ho_Chi_Minh.")); return; } const parsed = preferencesSchema.safeParse(draft); if (!parsed.success) { onToast(issue(parsed.error.issues[0]??{})); return; } const timeCheck=validateEventTimezone(data.events,parsed.data.timezone); if(!timeCheck.valid){onToast(localizeMessage(timeCheck.errors[0],true));return;} setData(s => ({ ...s, preferences: parsed.data })); onToast(tr("Preferences saved")); }
  return <div className="module-page"><SectionHeading eyebrow={tr("MAKE IT YOURS")} title={tr("A rhythm that fits you.")} text={tr("Small preferences that help Life OS understand your day.")} /><form className="module-settings-form" onSubmit={save}><section className="panel module-settings-section"><div className="module-settings-label"><Settings2 size={20} /><h2>{tr("The essentials")}</h2><p className="muted">{tr("Your name, your time, your space.")}</p></div><div className="form-grid">{input("displayName", tr("Display name"))}{input("timezone", tr("Timezone · IANA name"))}<label className="label">{tr("Language")}<select className="field" aria-label={tr("Language")} value={draft.language} onChange={e => update("language", e.target.value as "en" | "vi")}><option value="en">{tr("English")}</option><option value="vi">{tr("Tiếng Việt")}</option></select><small className="module-setting-help">{tr("Navigation and tools currently use English.")}</small></label><label className="label">{tr("Theme")}<select className="field" value={draft.theme} onChange={e => update("theme", e.target.value as Preferences["theme"])}><option value="light">{tr("Light")}</option><option value="dark">{tr("Dark")}</option><option value="system">{tr("Follow system")}</option></select></label><label className="label">{tr("Time format")}<select className="field" value={draft.timeFormat} onChange={e => update("timeFormat", e.target.value as "12" | "24")}><option value="24">{tr("24-hour · 16:00")}</option><option value="12">{tr("12-hour · 4:00 PM")}</option></select></label></div></section><section className="panel module-settings-section"><div className="module-settings-label"><Clock3 size={20} /><h2>{tr("Your daily rhythm")}</h2><p className="muted">{tr("Protected time for work and rest.")}</p></div><div className="form-grid">{input("wakeTime", tr("Wake-up time"), "time")}{input("bedTime", tr("Bedtime"), "time")}{input("mealTimes", tr("Preferred meal times"))}{input("focusHours", tr("Best focus hours"))}{input("breakMinutes", tr("Minutes between focus blocks"), "number")}</div></section><section className="panel module-settings-section"><div className="module-settings-label"><Dumbbell size={20} /><h2>{tr("Movement & energy")}</h2><p className="muted">{tr("Plan around the way you like to move.")}</p></div><div className="module-settings-fields"><div className="label">{tr("Preferred workout days")}<div className="module-day-picker">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d, i) => <button key={d} type="button" className={draft.workoutDays.includes(i) ? "selected" : ""} aria-pressed={draft.workoutDays.includes(i)} onClick={() => update("workoutDays", draft.workoutDays.includes(i) ? draft.workoutDays.filter(x => x !== i) : [...draft.workoutDays, i])}>{tr(d)}</button>)}</div></div><div className="form-grid">{input("workoutDuration", tr("Session length (minutes)"), "number")}{input("fitnessGoal", tr("Fitness goals"))}<label className="label">{tr("Experience")}<select className="field" value={draft.experience} onChange={e => update("experience", e.target.value)}><option value="Beginner">{tr("Beginner")}</option><option value="Intermediate">{tr("Intermediate")}</option><option value="Advanced">{tr("Advanced")}</option></select></label></div></div></section><section className="panel module-settings-section"><div className="module-settings-label"><Utensils size={20} /><h2>{tr("Food & wellbeing")}</h2><p className="muted">{tr("Everyday preferences for more useful suggestions.")}</p></div><div className="form-grid">{input("dietaryPreferences", tr("Dietary preferences"))}{input("allergies", tr("Allergies & foods to avoid"))}{input("budget", tr("Meal budget"))}{input("personalGoal", tr("Personal goals"))}</div></section><section className="panel module-settings-section"><div className="module-settings-label"><Bell size={20} /><h2>{tr("Gentle reminders")}</h2><p className="muted">{tr("A nudge before your next activity.")}</p></div><div className="module-notification-settings"><p>{tr("In-app reminders work while Life OS is open. Browser notifications also need this page to stay open.")}</p><p className="muted">{notification === "granted" ? tr("Browser notifications are enabled.") : notification === "denied" ? tr("Notifications are blocked. You can change permission in your browser’s site settings.") : notification === "unsupported" ? tr("This browser does not support notifications.") : tr("Browser notifications are optional. Enable them when you’re ready.")}</p><button type="button" className="btn btn-ghost" disabled={notification !== "default"} onClick={async () => { try { const permission = await Notification.requestPermission(); setNotification(permission); onToast(permission === "granted" ? tr("Browser reminders enabled while Life OS is open") : tr("Notification preference saved")); } catch { onToast(tr("This browser could not enable notifications. In-app reminders are still available.")); } }}><Bell size={16} />{notification === "granted" ? tr("Notifications enabled") : tr("Enable browser notifications")}</button></div></section><div className="module-settings-save"><p className="muted">{tr("Your preferences are included when you ask the AI to plan.")}</p><button className="btn btn-primary" type="submit"><Check size={17} />{tr("Save preferences")}</button></div></form></div>;
}

interface Proposal { id?: string; summary: string; events: LifeEvent[]; warnings?: string[]; changes?: { eventId: string; before: string; after: string; reason: string }[] }

export function AIPlannerView({ data, setData, selectedDate, onDateChange, onToast, aiConfigured }: ModuleProps & { aiConfigured?: boolean }) {
  const {t:tr,message:localizeMessage,issue,language,formatDuration,formatTime,calendarDayLabel:dayLabel,humanCategory}=useI18n();

  const [prompt, setPrompt] = useState("");
  const [scope,setScope]=useState<"day"|"week">("day");
  const [mode, setMode] = useState<"balanced" | "productive" | "relaxed">("balanced");
  const [generating, setGenerating] = useState(false);
  const [proposal, setProposal] = useState<Proposal | null>(null);
  const [clarification,setClarification]=useState('');
  const [error, setError] = useState("");
  const [editing, setEditing] = useState(false);
  const [originalEvents, setOriginalEvents] = useState<LifeEvent[]>([]);
  const validation = useMemo(() => { if (!proposal || !proposal.events.length) return { valid: true, errors: [] }; const parsed = planProposalSchema.safeParse(proposal); if (!parsed.success) return { valid: false, errors: parsed.error.issues.slice(0, 5).map(i => i.message) }; return validatePlan(parsed.data.events, data.events, data.preferences, data.tasks); }, [proposal, data.events, data.preferences, data.tasks]);
  async function generate() {
    if (prompt.trim().length < 5 || generating) return;
    setGenerating(true); setError("");setClarification('');
    try { const response = await fetch("/api/plan", { method: "POST", headers: { "Content-Type": "application/json", "Accept-Language":language }, body: JSON.stringify({ prompt, mode, scope, date: selectedDate, events: data.events, tasks: data.tasks, preferences: data.preferences }) }); const result = await response.json(); if (!response.ok) throw new Error(result.errorKey ?? result.error ?? tr("The planner is taking a break. Please try again.")); if(result.clarification){setProposal(null);setClarification(result.clarification);return;}if(result.date&&result.date!==selectedDate)onDateChange(result.date);if (!result.proposal || !Array.isArray(result.proposal.events)) throw new Error(tr("The planner returned an incomplete proposal. Please try again.")); setProposal(result.proposal); setOriginalEvents(data.events); setEditing(false); }
    catch (cause) { setError(cause instanceof Error ? cause.message : tr("We couldn’t reach the planner. Your schedule is unchanged.")); }
    finally { setGenerating(false); }
  }
  function accept() {
    if (!proposal || !validation.valid) return;
    if (JSON.stringify(data.events) !== JSON.stringify(originalEvents)) { setError(tr("Your schedule changed while this proposal was open. Generate a fresh proposal before applying it.")); return; }
    const accepted = proposal;
    setData(current => { return { ...current, events: applyEventOverlay(current.events, accepted.events, { materializeOccurrences: true }) }; });
    setProposal(null); setError(""); onToast(tr("Plan accepted. Your timeline is ready."));
  }
  return <div className="module-page module-ai-page"><SectionHeading eyebrow={tr("A LITTLE HELP GOES A LONG WAY")} title={tr("A good day starts with a plan.")} text={tr("Tell me what’s on your mind. We’ll find a little room for it.")} />
    <div className="module-toolbar"><div className="module-segment" aria-label={tr("Planning period")}>{(["day","week"] as const).map(period=><button key={period} disabled={generating} className={scope===period?"selected":""} onClick={()=>{setScope(period);setProposal(null);}}>{period==="day"?tr("Plan a day"):tr("Plan a week")}</button>)}</div><span className="muted small-text">{scope==="week"?`${dayLabel(selectedDate)} \u2013 ${dayLabel(shiftDate(selectedDate,6))}`:tr("A little clarity for one day")}</span></div><section className="panel module-ai-composer"><div className="module-ai-composer-top"><span className="module-ai-mark"><Sparkles size={24} /></span><div><h2>{scope==="week"?tr("Your week, thoughtfully arranged."):tr("Your day, thoughtfully arranged.")}</h2><p className="muted">{tr("A proposal first. You always make the final call.")}</p></div></div><label className="module-ai-prompt-label"><span className="sr-only">{tr("What would you like to plan?")}</span><textarea value={prompt} onChange={e => setPrompt(e.target.value)} maxLength={3000} placeholder={tr("Tomorrow I have classes from 7 to 11:30. Help me find time for 90 minutes at the gym, 3 hours of project work, and an hour of English…")} rows={5} /></label><div className="module-ai-composer-bottom"><input className="field module-date-input" aria-label={tr("AI plan date")} type="date" disabled={generating} value={selectedDate} onChange={e => { if (e.target.value) { onDateChange(e.target.value); setProposal(null); } }} /><span className="muted">{data.events.filter(e => e.fixed).length} {tr("fixed activities protected")}</span><button className="btn btn-primary" onClick={generate} disabled={generating || prompt.trim().length < 5 || aiConfigured === false}>{generating ? <LoaderCircle className="module-spin" size={17} /> : <Sparkles size={17} />}{generating ? tr("Finding your rhythm…") : tr("Create my plan")}</button></div></section>
    <div className="module-ai-modes">{([{ id: "balanced", icon: "◐", title: tr("Balanced"), text: tr("Focus, movement, and room to breathe.") }, { id: "productive", icon: "↗", title: tr("Productive"), text: tr("Give your important work a little more space.") }, { id: "relaxed", icon: "☁", title: tr("Relaxed"), text: tr("A gentler day, with longer breaks.") }] as const).map(m => <button key={m.id} className={`panel module-ai-mode ${mode === m.id ? "selected" : ""}`} onClick={() => setMode(m.id)} aria-pressed={mode === m.id}><span className="module-ai-mode-symbol">{m.icon}</span><div><strong>{m.title}</strong><p className="muted">{m.text}</p></div><span className="module-mode-radio">{mode === m.id && <span />}</span></button>)}</div>
    {aiConfigured === false && <div className="module-config-note"><Sparkles size={19} /><div><strong>{tr("Connect Gemini to bring your planner to life.")}</strong><p>{tr("Add")} <code>GEMINI_API_KEY</code> {tr("to")} <code>.env.local</code> {tr("and restart the app. Your timeline and all other tools work without AI.")}</p></div></div>}
    {clarification&&<section className="panel ai-clarification" role="status"><h3>{tr("ai.clarificationTitle")}</h3><p>{clarification}</p><small className="muted">{tr("ai.clarificationHint")}</small></section>}{error && <div role="alert" className="module-error"><strong>{tr("A little pause in planning")}</strong><p>{localizeMessage(error,true)}</p><span>{tr("Your current schedule has not changed.")}</span></div>}
    {proposal && <section className="module-proposal"><div className="module-section-heading"><div><span className="eyebrow">{tr("YOUR PROPOSED PLAN")}</span><h2>{tr("A little more clarity.")}</h2></div><span className="badge">{tr("Preview · not applied")}</span></div><p className="muted module-proposal-summary">{proposal.summary}</p>{proposal.warnings?.map((warning, i) => <p className="module-plan-warning" key={i}>{warning}</p>)}<div className="module-proposal-events">{proposal.events.map((event, i) => <article className={`panel module-proposed-event category-${event.category}`} key={event.id}><div className="module-proposed-time">{event.startTime}<ArrowDown size={13} />{event.endTime}</div><div className="module-proposed-content">{editing ? <><input className="field" aria-label={tr("Proposed activity {p0} title", {p0: i + 1})} value={event.title} onChange={e => setProposal(p => p && ({ ...p, events: p.events.map(x => x.id === event.id ? { ...x, title: e.target.value } : x) }))} /><div className="module-proposed-edit-times"><input className="field" type="date" aria-label={tr("Proposed activity {p0} date", {p0: i + 1})} value={event.date} onChange={e => setProposal(p => p && ({ ...p, events: p.events.map(x => x.id === event.id ? { ...x, date: e.target.value } : x) }))} />{(["startTime", "endTime"] as const).map(k => <input className="field" key={k} aria-label={tr("Proposed activity {p0} {p1}", {p0: i + 1, p1: tr(k==='startTime'?'Starts at':'Ends at')})} type="time" value={event[k]} onChange={e => setProposal(p => p && ({ ...p, events: p.events.map(x => x.id === event.id ? { ...x, [k]: e.target.value } : x) }))} />)}</div></> : <><span className="eyebrow">{humanCategory(event.category)} {event.fixed ? tr("· Fixed") : ""} · {dayLabel(event.date)}</span><h3>{event.title}</h3>{event.description && <p className="muted">{event.description}</p>}</>}</div></article>)}</div>{proposal.changes && proposal.changes.length > 0 && <div className="panel module-changes"><h3>{tr("What changes")}</h3>{proposal.changes.map((change, i) => <div key={i}><span>{change.before}</span><ArrowRight size={14} /><strong>{change.after}</strong><p className="muted">{change.reason}</p></div>)}</div>}{!validation.valid && <div className="module-error" role="alert"><strong>{tr("This plan needs a small adjustment.")}</strong>{validation.errors.map((message, i) => <p key={i}>{localizeMessage(message,true)}</p>)}</div>}<div className="module-proposal-actions"><button className="btn btn-ghost" onClick={() => { setProposal(null); setError(""); onToast(tr("Proposal dismissed. Your schedule is unchanged.")); }}>{tr("Cancel")}</button><button className="btn btn-ghost" onClick={generate} disabled={generating}>{generating ? <LoaderCircle size={16} className="module-spin" /> : <Sparkles size={16} />}{tr("Regenerate")}</button><button className="btn btn-ghost" onClick={() => setEditing(!editing)}><Pencil size={16} />{editing ? tr("Finish editing") : tr("Edit plan")}</button><button className="btn btn-primary" disabled={!validation.valid || generating || !proposal.events.length} onClick={accept}><Check size={17} />{tr("Accept plan")}</button></div></section>}
    {!proposal && !generating && <div className="module-ai-principles"><div><span>01</span><strong>{tr("Your real schedule")}</strong><p className="muted">{tr("Plans begin with your existing activities, deadlines, and preferences.")}</p></div><div><span>02</span><strong>{tr("The important things stay")}</strong><p className="muted">{tr("Fixed commitments stay protected. Conflicts are checked before applying.")}</p></div><div><span>03</span><strong>{tr("You’re always in control")}</strong><p className="muted">{tr("Review every block, adjust the details, then accept when it feels right.")}</p></div></div>}
  </div>;
}
